<?php use FilamentManager\Core\View; ?>
<h1><?= View::t('users') ?></h1><div class="grid users-grid"><section class="card"><div class="toolbar"><h2><?= $editing?View::t('edit_user'):View::t('new_user') ?></h2><?php if($editing): ?><a class="button secondary-button action-button" href="<?= View::e($basePath) ?>/admin/users"><?= View::t('cancel') ?></a><?php endif; ?></div><form method="post" action="<?= View::e($basePath) ?><?= $editing?'/admin/users/'.View::e($editing['id']):'/admin/users' ?>"><?= View::csrf() ?><label><?= View::t('username') ?><input name="username" required value="<?= View::e($editing['username']??'') ?>"></label><label><?= View::t('display_name') ?><input name="display_name" value="<?= View::e($editing['display_name']??'') ?>"></label><label><?= View::t('email') ?><input name="email" type="email" value="<?= View::e($editing['email']??'') ?>"></label><label><?= View::t('password') ?><input name="password" type="password" minlength="12" <?= $editing?'':'required' ?> autocomplete="new-password"><?php if($editing): ?><small><?= View::t('password_unchanged') ?></small><?php endif; ?></label><label><?= View::t('role') ?><select name="role" <?= $editing&&$editing['id']===$app->auth()->user()['id']?'disabled':'' ?>><?php foreach(['viewer','operator','manager','admin'] as $role): ?><option value="<?= $role ?>" <?= ($editing['role']??'viewer')===$role?'selected':'' ?>><?= View::t('role_'.$role) ?></option><?php endforeach; ?></select><?php if($editing&&$editing['id']===$app->auth()->user()['id']): ?><input type="hidden" name="role" value="admin"><?php endif; ?></label><label><?= View::t('language') ?><select name="locale"><option value="cs" <?= ($editing['locale']??'cs')==='cs'?'selected':'' ?>>Čeština</option><option value="en" <?= ($editing['locale']??'cs')==='en'?'selected':'' ?>>English</option></select></label>
<fieldset class="notification-settings"><legend><?= View::t('email_notifications') ?></legend><p class="muted"><?= View::t('email_notifications_help') ?></p><label class="check-label"><input type="checkbox" name="notification_enabled" value="1" <?= !empty($editing['notification_enabled'])?'checked':'' ?>> <?= View::t('enable_email_notifications') ?></label><label class="check-label"><input type="checkbox" name="notify_spool_empty" value="1" <?= !isset($editing['notify_spool_empty'])||$editing['notify_spool_empty']?'checked':'' ?>> <?= View::t('notify_spool_empty') ?></label><div class="notification-limit"><label class="check-label"><input type="checkbox" name="notify_low_spool_weight" value="1" <?= !isset($editing['notify_low_spool_weight'])||$editing['notify_low_spool_weight']?'checked':'' ?>> <?= View::t('notify_low_spool_weight') ?></label><label><?= View::t('weight_limit_g') ?><input type="number" name="low_spool_weight_g" min="0" max="100000" step="1" value="<?= View::e($editing['low_spool_weight_g']??100) ?>"></label></div><label class="check-label"><input type="checkbox" name="notify_material_out" value="1" <?= !isset($editing['notify_material_out'])||$editing['notify_material_out']?'checked':'' ?>> <?= View::t('notify_material_out') ?></label><div class="notification-limit"><label class="check-label"><input type="checkbox" name="notify_low_material_count" value="1" <?= !empty($editing['notify_low_material_count'])?'checked':'' ?>> <?= View::t('notify_low_material_count') ?></label><label><?= View::t('spool_count_limit') ?><input type="number" name="low_material_count" min="0" max="9999" value="<?= View::e($editing['low_material_count']??1) ?>"></label></div><label class="check-label"><input type="checkbox" name="notify_location_full" value="1" <?= !empty($editing['notify_location_full'])?'checked':'' ?>> <?= View::t('notify_location_full') ?></label></fieldset><button class="action-button"><?= View::t('save') ?></button></form></section>
<section><div class="table-wrap"><table class="users-table"><thead><tr><th><?= View::t('username') ?></th><th><?= View::t('role') ?></th><th><?= View::t('email') ?></th><th><?= View::t('email_notifications') ?></th><th><?= View::t('status') ?></th><th><?= View::t('last_login') ?></th><th></th></tr></thead><tbody><?php foreach($users as $user): ?><tr><td><strong><?= View::e($user['display_name']) ?></strong><br><small><?= View::e($user['username']) ?></small></td><td><?= View::t('role_'.$user['role']) ?></td><td class="user-email"><?= View::e($user['email']?:'—') ?></td><td><?= $user['notification_enabled']?View::t('enabled'):View::t('disabled') ?></td><td><?= $user['is_active']?View::t('active'):View::t('disabled') ?></td><td><?= View::e(View::dateTime($user['last_login_at']??null)) ?></td><td><div class="actions"><a class="button secondary-button action-button" href="<?= View::e($basePath) ?>/admin/users/<?= View::e($user['id']) ?>/edit"><?= View::t('edit') ?></a><?php if($user['id']!==$app->auth()->user()['id']): ?><form method="post" action="<?= View::e($basePath) ?>/admin/users/<?= View::e($user['id']) ?>/toggle"><?= View::csrf() ?><button class="secondary-button action-button"><?= $user['is_active']?View::t('disable'):View::t('enable') ?></button></form><form method="post" action="<?= View::e($basePath) ?>/admin/users/<?= View::e($user['id']) ?>/delete"><?= View::csrf() ?><button class="danger-button action-button"><?= View::t('delete') ?></button></form><?php endif; ?></div></td></tr><?php endforeach; ?></tbody></table></div></section></div>
